/** Resolve a wall-clock time, choosing the earlier instant in a repeated hour
 * and moving forward by the gap when a clock time does not exist. */
export function localDateTime(day: string, hour: number, timeZone: string): IsoTimestamp {
  const [year, month, date] = day.split("-").map(Number);
  const wall = Date.UTC(year, month - 1, date, hour);
  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone, year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23",
  });
  const wallAt = (instant: number) => {
    const parts = formatter.formatToParts(new Date(instant));
    const n = (name: string) => Number(parts.find((p) => p.type === name)!.value);
    return Date.UTC(n("year"), n("month") - 1, n("day"), n("hour"), n("minute"), n("second"));
  };
  const offsets = new Set([-2, -1, 0, 1, 2].map((d) => {
    const instant = wall + d * DAY_MS;
    return wallAt(instant) - instant;
  }));
  const candidates = [...offsets].map((offset) => wall - offset);
  const exact = candidates.filter((instant) => wallAt(instant) === wall).sort((a, b) => a - b);
  if (exact.length) return toIsoTimestamp(new Date(exact[0]));
  const after = candidates.filter((instant) => wallAt(instant) > wall)
    .sort((a, b) => wallAt(a) - wallAt(b));
  return toIsoTimestamp(new Date(after[0]));
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return localDateTime(localDate(toIsoTimestamp(reference), timeZone), 0, timeZone);
